// Generates the PWA icon set with a tiny, dependency-free PNG encoder.
//
// The mark is a white leaf on the brand teal (#0d9488). Rasterising it here
// keeps the icons reproducible (run `npm run icons`) instead of committing
// opaque binaries generated by an external tool.
//
// Usage: node scripts/generate-icons.mjs

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { deflateSync } from 'node:zlib';

const __dirname = dirname(fileURLToPath(import.meta.url));
const rootDir = join(__dirname, '..');
const iconsDir = join(rootDir, 'public', 'icons');

const TEAL = [13, 148, 136]; // --color-primary (#0d9488)
const WHITE = [255, 255, 255];

// ---- PNG encoding -----------------------------------------------------------

const crcTable = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(buffer) {
  let crc = 0xffffffff;
  for (let i = 0; i < buffer.length; i += 1) {
    crc = crcTable[(crc ^ buffer[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const typeBuffer = Buffer.from(type, 'ascii');
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([typeBuffer, data])), 0);
  return Buffer.concat([length, typeBuffer, data, crc]);
}

function encodePng(size, pixels) {
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // colour type: RGBA
  // bytes 10-12: compression, filter, interlace = 0

  const rowLength = size * 4;
  const raw = Buffer.alloc((rowLength + 1) * size);
  for (let y = 0; y < size; y += 1) {
    raw[y * (rowLength + 1)] = 0; // filter type "None"
    pixels.copy(raw, y * (rowLength + 1) + 1, y * rowLength, y * rowLength + rowLength);
  }

  const idat = deflateSync(raw, { level: 9 });
  return Buffer.concat([
    signature,
    chunk('IHDR', ihdr),
    chunk('IDAT', idat),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

// ---- Geometry helpers -------------------------------------------------------

function insideRoundedSquare(x, y, size, radius) {
  if (x < 0 || y < 0 || x > size || y > size) return false;
  const min = radius;
  const max = size - radius;
  const qx = Math.min(Math.max(x, min), max);
  const qy = Math.min(Math.max(y, min), max);
  const dx = x - qx;
  const dy = y - qy;
  return dx * dx + dy * dy <= radius * radius;
}

function insideLeaf(x, y, geometry) {
  const { cx, cy, halfWidth: a, halfHeight: b } = geometry;
  const radius = (a * a + b * b) / (2 * a);
  const offset = radius - a;
  const dy = y - cy;
  const left = x - (cx - offset);
  const right = x - (cx + offset);
  return left * left + dy * dy <= radius * radius && right * right + dy * dy <= radius * radius;
}

function insideStem(x, y, geometry) {
  const { cx, cy, halfHeight: b, stemLength, stemWidth } = geometry;
  const top = cy + b * 0.92;
  const bottom = top + stemLength;
  if (y < top - stemWidth / 2 || y > bottom + stemWidth / 2) return false;
  const clampedY = Math.min(Math.max(y, top), bottom);
  const dx = x - cx;
  const dy = y - clampedY;
  return dx * dx + dy * dy <= (stemWidth / 2) * (stemWidth / 2);
}

// ---- Rasterising ------------------------------------------------------------

const SUPERSAMPLE = 4;

function renderIcon(size, { fullBleed, scale }) {
  const pixels = Buffer.alloc(size * size * 4);
  const radius = fullBleed ? 0 : size * 0.22;

  const geometry = {
    cx: size / 2,
    cy: size * 0.46,
    halfWidth: size * 0.15 * scale,
    halfHeight: size * 0.3 * scale,
    stemWidth: size * 0.05 * scale,
    stemLength: size * 0.1 * scale,
  };

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      let red = 0;
      let green = 0;
      let blue = 0;
      let opaque = 0;

      for (let sy = 0; sy < SUPERSAMPLE; sy += 1) {
        for (let sx = 0; sx < SUPERSAMPLE; sx += 1) {
          const px = x + (sx + 0.5) / SUPERSAMPLE;
          const py = y + (sy + 0.5) / SUPERSAMPLE;

          let colour = null;
          if (insideLeaf(px, py, geometry) || insideStem(px, py, geometry)) colour = WHITE;
          else if (fullBleed || insideRoundedSquare(px, py, size, radius)) colour = TEAL;

          if (colour) {
            red += colour[0];
            green += colour[1];
            blue += colour[2];
            opaque += 1;
          }
        }
      }

      const samples = SUPERSAMPLE * SUPERSAMPLE;
      const index = (y * size + x) * 4;
      pixels[index] = opaque ? Math.round(red / opaque) : 0;
      pixels[index + 1] = opaque ? Math.round(green / opaque) : 0;
      pixels[index + 2] = opaque ? Math.round(blue / opaque) : 0;
      pixels[index + 3] = Math.round((opaque / samples) * 255);
    }
  }

  return encodePng(size, pixels);
}

// ---- Output -----------------------------------------------------------------

mkdirSync(iconsDir, { recursive: true });

const outputs = [
  // Standard "any" icons: rounded tile, full mark.
  { path: join(iconsDir, 'icon-192.png'), size: 192, options: { fullBleed: false, scale: 1 } },
  { path: join(iconsDir, 'icon-512.png'), size: 512, options: { fullBleed: false, scale: 1 } },
  // Maskable: full-bleed background, mark scaled into the 80% safe zone.
  { path: join(iconsDir, 'icon-maskable-512.png'), size: 512, options: { fullBleed: true, scale: 0.78 } },
  // Browser favicon and iOS home-screen icon.
  { path: join(rootDir, 'public', 'favicon.png'), size: 64, options: { fullBleed: false, scale: 1 } },
  { path: join(rootDir, 'public', 'apple-touch-icon.png'), size: 180, options: { fullBleed: true, scale: 0.82 } },
];

for (const output of outputs) {
  writeFileSync(output.path, renderIcon(output.size, output.options));
  console.log(`wrote ${output.path.replace(`${rootDir}/`, '')}`);
}
